 * call in product_config.asm, so a control build is the pre-fix
 * image -- the same md5, not merely the same behaviour. That is what
 * makes every cycle figure recorded before 2026-09-09 reproducible
 * on this tree. */
#if DSP4_CHAN_MASK

.section/dm seg_dmda;

